-- TOC entry 265 (class 1259 OID 17735)
-- Name: vehicle_export_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vehicle_export_view AS
 SELECT v.id,
    v.dealer_id,
    v.vin,
    v.make,
    v.model,
    v.year,
    v."trim",
    v.color,
    v.mileage,
    v.price,
    v.description,
    v.features,
    v.images,
    v.status,
    v.qr_code_url,
    v.created_at,
    v.updated_at,
    v.stock_number,
    v.body_style,
    v.certified,
    v.interior_color,
    v.engine_type,
    v.displacement,
    v.transmission,
    v.msrp,
    v.dealer_discount,
    v.consumer_rebate,
    v.dealer_accessories,
    v.total_customer_savings,
    v.total_dealer_rebate,
    v.other_price,
    v.photo_url_list,
    v.odometer,
    v.import_source,
    v.import_date,
    v.series,
    v.reference_dealer_id,
    v.new_used,
    d.business_name AS dealer_name
   FROM (public.vehicles v
     LEFT JOIN public.dealers d ON ((v.dealer_id = d.id)));


ALTER VIEW public.vehicle_export_view OWNER TO postgres;

